gQ4(){return"\u0627\u0644\u0645\u0624\u062a\u0645\u0631 \u0627\u0644\u0635\u062d\u0641\u064a"},
gaKs(){return"\u0648\u0627\u062b\u0642"},
gaKt(){return"\u0627\u0644\u062e\u0635\u0645 \u0633\u064a\u0633\u0645\u0639 \u0630\u0644\u0643"},
gaKu(){return"\u062f\u0628\u0644\u0648\u0645\u0627\u0633\u064a"},
gaKv(){return"\u0644\u0646 \u064a\u0646\u0632\u0639\u062c \u0623\u062d\u062f"},
gaKw(){return"\u0645\u062d\u0641\u0651\u0632"},
gaKx(){return"\u0641\u0631\u064a\u0642\u0643 \u0633\u064a\u0633\u0645\u0639 \u0647\u0630\u0627"},
gaKy(){return"\u0638\u0631\u064a\u0641"},
gaKz(){return"\u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u062a\u062d\u0628\u0647\u060c \u0644\u0643\u0646 \u0644\u064a\u0633 \u0627\u0644\u062c\u0645\u064a\u0639"},
