gaKp(){return"\u0633\u0644\u0633\u0644\u0629"},
gaKo(){return"\u0627\u0644\u0644\u0639\u0628"},
gaKl(){return"\u0622\u062e\u0631 \u0627\u0644\u0623\u062e\u0628\u0627\u0631"},
gaKk(){return"\u062a\u0639\u0630\u0651\u0631 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0625\u062c\u0627\u0628\u0627\u062a \u2014 \u0631\u0628\u0645\u0627 \u0627\u0646\u062a\u0647\u062a \u0627\u0644\u0645\u0647\u0644\u0629."},
gaK5(){return"\u062a\u062c\u064a\u0628 \u0639\u0646 \u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u0645\u0631\u0627\u0633\u0644\u064a\u0646 \u0628\u0627\u062e\u062a\u064a\u0627\u0631 \u0646\u0628\u0631\u0629: \u0648\u0627\u062b\u0642\u0629 \u0623\u0648 \u062f\u0628\u0644\u0648\u0645\u0627\u0633\u064a\u0629 \u0623\u0648 \u0645\u062d\u0641\u0651\u0632\u0629 \u0623\u0648 \u0638\u0631\u064a\u0641\u0629. \u062a\u062a\u0648\u0644\u0649 \u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0635\u064a\u0627\u063a\u0629 \u0646\u0635 \u0625\u062c\u0627\u0628\u062a\u0643 \u2014 \u0648\u0623\u0646\u062a \u062a\u062d\u062f\u062f \u0627\u0644\u0645\u0648\u0642\u0641.\n\n\u0627\u0644\u0646\u0628\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u062e\u062a\u0627\u0631\u0647\u0627 \u062a\u0646\u0639\u0643\u0633 \u0639\u0644\u0649 \u0645\u0639\u0646\u0648\u064a\u0627\u062a \u0641\u0631\u064a\u0642\u0643 \u0648\u0646\u0638\u0631\u0629 \u0627\u0644\u062c\u0645\u0627\u0647\u064a\u0631 \u0625\u0644\u064a\u0643. \u0623\u0645\u0627\u0645\u0643 \u064a\u0648\u0645\u0627\u0646 \u0644\u0644\u0625\u062c\u0627\u0628\u0629 \u0639\u0646 \u0643\u0644 \u0645\u0624\u062a\u0645\u0631\u061b \u0648\u0625\u0630\u0627 \u0627\u0646\u062a\u0647\u062a \u0627\u0644\u0645\u0647\u0644\u0629 \u062a\u0643\u062a\u0628 \u0627\u0644\u0635\u062d\u0627\u0641\u0629 \xab\u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0641\u0646\u064a \u0644\u0645 \u064a\u062d\u0636\u0631\xbb.\n\n\u0639\u0646\u062f \u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0645\u0624\u062a\u0645\u0631\u060c \u062a\u0638\u0647\u0631 \u0625\u062c\u0627\u0628\u0627\u062a\u0643 \u0641\u064a \u0622\u062e\u0631 \u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u0641\u064a \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u062a\u0627\u0644\u064a."},
gaK0(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0624\u062a\u0645\u0631 \u0635\u062d\u0641\u064a \u0645\u0641\u062a\u0648\u062d \u062d\u0627\u0644\u064a\u064b\u0627."},
gaK_(){return"\u0639\u0646\u062f \u0641\u062a\u062d \u0645\u0624\u062a\u0645\u0631 \u062a\u0635\u0644\u0643 \u0628\u0637\u0627\u0642\u0629 \u0641\u064a \u0627\u0644\u0645\u0643\u062a\u0628 \u2014 \u0648\u0645\u0646\u0647\u0627 \u062a\u064f\u0633\u062a\u062f\u0639\u0649 \u0625\u0644\u0649 \u0627\u0644\u0642\u0627\u0639\u0629."},
gPZ(){return"\u0633\u0624\u0627\u0644"},
gPY(){return"\u0625\u062c\u0627\u0628\u062a\u0643 \u062a\u0628\u0642\u0649 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0635\u0629 \u2014 \u0644\u0627 \u064a\u0645\u0643\u0646 \u062a\u063a\u064a\u064a\u0631\u0647\u0627 \u0644\u0627\u062d\u0642\u064b\u0627."},
gaK8(){return"\u0628\u0639\u062f \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629"},
gaKc(){return"\u0642\u0628\u0644 \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629"},
gaKj(){return"\u0627\u0644\u0642\u0627\u0639\u0629 \u0645\u0641\u062a\u0648\u062d\u0629"},
gaKB(){return"\u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0641\u064a \u0627\u0646\u062a\u0638\u0627\u0631\u0643"},
gaKA(){return"\u0627\u0644\u0645\u0647\u0644\u0629 \u062a\u0648\u0634\u0643 \u0639\u0644\u0649 \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u2014 \u0625\u0646 \u0644\u0645 \u062a\u062d\u0636\u0631 \u062a\u0643\u062a\u0628 \u0627\u0644\u0635\u062d\u0627\u0641\u0629 \xab\u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0641\u0646\u064a \u0644\u0645 \u064a\u0648\u0627\u062c\u0647 \u0627\u0644\u0635\u062d\u0627\u0641\u0629\xbb."},
gaKC(){return"\u0623\u0645\u0627\u0645\u0643 \u064a\u0648\u0645\u0627\u0646 \u0644\u0644\u0625\u062c\u0627\u0628\u0629\u061b \u0648\u0625\u0630\u0627 \u0627\u0646\u062a\u0647\u062a \u0627\u0644\u0645\u0647\u0644\u0629 \u064a\u0641\u0648\u062a\u0643 \u0627\u0644\u0645\u0624\u062a\u0645\u0631."},
