gaK7(){return"\u0627\u062e\u062a\u0631 \u0646\u0628\u0631\u0629"},
gaK1(){return"\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0645\u0624\u062a\u0645\u0631"},
gaK6(){return"\u0627\u0644\u0633\u0624\u0627\u0644 \u0627\u0644\u062a\u0627\u0644\u064a"},
gaJZ(){return"\u0627\u0643\u062a\u0645\u0644 \u0627\u0644\u0645\u0624\u062a\u0645\u0631"},
gaJX(){return"\u0633\u062a\u0638\u0647\u0631 \u0625\u062c\u0627\u0628\u0627\u062a\u0643 \u063a\u062f\u064b\u0627 \u0641\u064a "},
gaJY(){return" \u2014 \u062a\u0627\u0628\u0639 \u0631\u062f\u0648\u062f \u0641\u0639\u0644 \u0627\u0644\u062c\u0645\u0627\u0647\u064a\u0631 \u0647\u0646\u0627\u0643."},
gaK2(){return"\u0625\u0644\u0649 \u0622\u062e\u0631 \u0627\u0644\u0623\u062e\u0628\u0627\u0631"},
gaO0(){return"\u0644\u0627 \u0631\u062c\u0639\u0629 \u0641\u064a\u0647"},
gaO1(){return"\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0625\u0639\u0644\u0627\u0646"},
gaO2(){return"\u0625\u0630\u0627 \u0648\u0631\u062f \u0639\u0631\u0636 \u0648\u0627\u062d\u062f \u0628\u0647\u0630\u0627 \u0627\u0644\u0633\u0639\u0631 \u064a\u064f\u0628\u0627\u0639 \u0627\u0644\u0644\u0627\u0639\u0628. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0633\u062d\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0646."},
gaO_(){return"\u0641\u062a\u062d \u0627\u0644\u0625\u0639\u0644\u0627\u0646"},
gQK(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0648\u0643\u0627\u0644\u0629 \u062a\u0642\u062f\u0645 \u0639\u0631\u0636\u064b\u0627 \u062d\u0627\u0644\u064a\u064b\u0627 \u2014 \u062d\u0627\u0648\u0644 \u0644\u0627\u062d\u0642\u064b\u0627."},
gaOf(){return"\u062a\u0642\u062f\u0645 \u0627\u0644\u0648\u0643\u0627\u0644\u0627\u062a \u0639\u0631\u0648\u0636 \u0627\u0644\u062a\u0645\u062b\u064a\u0644. \u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u0627\u0644\u0643\u0628\u064a\u0631\u0629 \u062a\u0635\u0644 \u0625\u0644\u0649 \u062f\u0627\u0626\u0631\u0629 \u0623\u0648\u0633\u0639 \u0645\u0646 \u0627\u0644\u0623\u0646\u062f\u064a\u0629\u061b \u0648\u0645\u0627 \u064a\u0635\u0644\u0643 \u0645\u0646 \u062d\u0635\u0629 \u064a\u062e\u062a\u0644\u0641 \u0628\u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0644\u0648\u0643\u0627\u0644\u0629."},
gaOg(){return"\u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u062a\u0642\u062a\u0631\u062d \u0633\u0639\u0631 \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u060c \u0648\u0627\u0644\u0642\u0631\u0627\u0631 \u0644\u0643. \u0625\u0630\u0627 \u0627\u062e\u062a\u0631\u062a \u0633\u0639\u0631\u064b\u0627 \u0623\u0642\u0644 \u0628\u0643\u062b\u064a\u0631 \u0645\u0646 \u0642\u064a\u0645\u0629 \u0627\u0644\u0644\u0627\u0639\u0628 \u0641\u0633\u064a\u0638\u0647\u0631 \u0644\u0643 \u062a\u062d\u0630\u064a\u0631."},
gaOh(){return"\u0628\u0639\u062f \u0627\u0644\u062a\u0623\u0643\u064a\u062f \u0644\u0627 \u064a\u0645\u0643\u0646 \u0633\u062d\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0646. \u062d\u062a\u0649 \u0644\u0648 \u0648\u0631\u062f \u0639\u0631\u0636 \u0648\u0627\u062d\u062f \u0628\u0647\u0630\u0627 \u0627\u0644\u0633\u0639\u0631 \u064a\u064f\u0628\u0627\u0639 \u0627\u0644\u0644\u0627\u0639\u0628."},
gaO3(){return"\u0627\u0639\u0631\u0636\u0647 \u0644\u0644\u0628\u064a\u0639"},
gaOl(){return"\u0633\u0639\u0631 \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d \u0627\u0644\u0630\u064a \u0627\u062e\u062a\u0631\u062a\u0647 \u0623\u0642\u0644 \u0628\u0648\u0636\u0648\u062d \u0645\u0646 \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0633\u0648\u0642\u064a\u0629. \u0625\u0630\u0627 \u0648\u0631\u062f \u0639\u0631\u0636 \u0648\u0627\u062d\u062f \u064a\u0631\u062d\u0644 \u0627\u0644\u0644\u0627\u0639\u0628 \u0628\u0647\u0630\u0627 \u0627\u0644\u0645\u0628\u0644\u063a."},
gEA(){return"\u0644\u0627\u0639\u0628 \u062a\u0639\u0627\u0642\u062f\u062a \u0645\u0639\u0647 \u062d\u062f\u064a\u062b\u064b\u0627: \u0633\u0639\u0631 \u0627\u0641\u062a\u062a\u0627\u062d\u0647 \u0642\u0631\u064a\u0628 \u062d\u0627\u0644\u064a\u064b\u0627 \u0645\u0646 \u0645\u0628\u0644\u063a \u0634\u0631\u0627\u0626\u0647\u060c \u0648\u0645\u0639 \u0627\u0644\u0648\u0642\u062a \u064a\u0639\u0643\u0633 \u0642\u064a\u0645\u062a\u0647 \u0627\u0644\u0633\u0648\u0642\u064a\u0629."},
gQN(){return"\u0645\u0646 \u064a\u062a\u0648\u0644\u0649 \u0627\u0644\u0628\u064a\u0639\u061f"},
gaOn(){return"\u0625\u0646 \u0628\u064a\u0639 \u064a\u0635\u0644\u0643"},
gaOm(){return"\u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0633\u0648\u0642\u064a\u0629"},
gaOe(){return"\u062f\u0627\u0626\u0631\u0629 \u0623\u0648\u0633\u0639 \u0645\u0646 \u0627\u0644\u0623\u0646\u062f\u064a\u0629"},
gaOd(){return"\u0645\u0627 \u064a\u0635\u0644\u0643 \u0645\u0646 \u062d\u0635\u0629"},
aOD(a,b,c){return"\u0633\u064a\u064f\u0639\u0631\u0636 "+a+" \u0641\u064a \u0627\u0644\u0645\u0632\u0627\u062f \u0628\u062a\u0645\u062b\u064a\u0644 \u0645\u0646 "+b+"\u060c \u0628\u0633\u0639\u0631 \u0627\u0641\u062a\u062a\u0627\u062d "+c+"."},
aOE(a,b,c,d){return"\u0633\u064a\u064f\u0639\u0631\u0636 "+a+" \u0641\u064a \u0627\u0644\u0645\u0632\u0627\u062f \u0628\u062a\u0645\u062b\u064a\u0644 \u0645\u0646 "+b+"\u060c \u0628\u0633\u0639\u0631 \u0627\u0641\u062a\u062a\u0627\u062d "+c+"\u061b "+d+"."},
aOF(a){return"\u0625\u0646 \u0628\u064a\u0639 \u064a\u0635\u0644\u0643 \u0646\u062d\u0648 "+a+"."},
gaOG(){return"\u064a\u0628\u0642\u0649 \u0641\u064a \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u0637\u0648\u0627\u0644 \u0627\u0644\u0645\u0632\u0627\u062f."},
